vi:{lg:"Ngôn ngữ",th:"Đổi giao diện",n1:"Dữ liệu",n2:"Cách hoạt động",n3:"Thử linter",n4:"Ví dụ",n5:"Video",h0:"Một skill của Claude cho slide",h1:'Slide có <span class="u">lập luận</span>',
h2:"Plinth viết tiêu đề trước, giao cho mỗi slide một việc, rồi rà từng chữ để bỏ câu thừa. Dành cho pitch hackathon, deck gọi vốn và bài nói.",
c1:"Kiểm tra deck ngay",c2:"Lấy skill",cp:"Sao chép",x1:"Tỷ lệ gốc",x2:"Điều không quan trọng",x3:"Điều quan trọng",x4:"Kết luận",x5:"số chữ trung vị, cả hai nhóm",
m1:"Cứ mười tám dự án thì một dự án đoạt giải",m2:"Đội thắng viết câu giới thiệu dài như mọi người",m3:"Đội thắng thường xây dựng công khai hơn hẳn",m4:"Hình thức chỉ là điều kiện tối thiểu. Lập luận mới quyết định.",
d0:"Nghiên cứu",d1:"Chúng tôi so sánh mọi đội thắng Colosseum với các dự án không đoạt giải",d2:"Những thứ được trau chuốt nhiều nhất hóa ra giống hệt nhau ở cả hai nhóm. Quy tắc của Plinth đến từ phần còn lại.",
s1:"dự án được lập chỉ mục",s2:"dự án đoạt giải",s3:"tỷ lệ thắng",s4:"giới hạn thời gian pitch",b1:"Có liên kết X, đội thắng",b2:"Có liên kết X, còn lại",b3:"Từ ngữ phô trương, đội thắng",b4:"Từ ngữ phô trương, còn lại",
src:"Nguồn: API Colosseum Copilot, mẫu 363 dự án qua 15 truy vấn danh mục, lấy ngày 25 tháng 9 năm 2026. Hướng dẫn chấm từ blog.colosseum.com.",
w0:"Cách hoạt động",w1:"Tiêu đề trước, slide sau, kiểm tra cuối",t1:"Viết lập luận thành các khẳng định",p1:"Mỗi tiêu đề là một câu đủ nghĩa có động từ. Đọc từ trên xuống, riêng danh sách tiêu đề đã phải thuyết phục.",
t2:"Mỗi slide một việc",p2:"Một con số, một biểu đồ, một ảnh chụp màn hình, hoặc ba ý ngắn. Một file HTML có ghi chú người nói và in ra PDF.",t3:"Rà từng chữ",p3:"Câu thừa, tiêu đề chỉ là nhãn chủ đề, slide quá tải và số liệu không nguồn đều bị đánh dấu trước khi ai nhìn thấy.",
l0:"Thử",l1:"Dán slide của bạn và xem giám khảo sẽ để ý điều gì",l2:'Dòng đầu mỗi slide là tiêu đề. Ngăn cách slide bằng một dòng ba gạch ngang. Thêm "source:" dưới mỗi con số. Không dữ liệu nào rời khỏi trình duyệt của bạn.',
pb:"Nạp deck yếu",pg:"Nạp bản viết lại",pc:"Xóa",k0:"Ví dụ",k1:"Hai deck làm bằng skill này, cả hai đạt 100 điểm",
e1:"5.428 dự án hackathon nói gì về cách pitch",e2:"Bài nói · 9 slide · dùng phím mũi tên để trình chiếu",e3:"Plinth, được pitch bằng Plinth",e4:"Pitch · 8 slide · thẳng thắn về việc chưa có người dùng",
v0:"Hướng dẫn",v1:"Xem một deck đi từ dàn ý đến 100 điểm",v2:"Đoạn quay màn hình ngắn: skill viết bộ khung tiêu đề, dựng slide, rồi kiểm tra và sửa câu chữ.",v3:"Video hướng dẫn skill Plinth.",
r0:"Quy tắc",r1:"Tám quy tắc skill không bao giờ phá",q1:"Tiêu đề là một khẳng định, không phải nhãn chủ đề.",q2:"Tối đa mười hai chữ mỗi tiêu đề.",q3:"Mỗi slide một bằng chứng.",q4:"Mọi con số đều kèm nguồn.",
q5:"Một màu nhấn, đặt ở nơi mắt cần dừng lại.",q6:"Không emoji, không dấu chấm than, không chữ gradient.",q7:"Dữ liệu còn thiếu được ghi rõ trên slide, không bịa ra.",q8:"Dưới ba phút cho pitch hackathon.",f1:"Làm bởi Bryan Kwandou. Giấy phép MIT."},

